import{_ as r}from"./chunks/setup.BSGJNh3a.js";import{_ as t,o as l,c as n,a2 as i}from"./chunks/framework.DSc8fo6x.js";const p=JSON.parse('{"title":"Quraşdırma və ilk açılış","description":"","frontmatter":{},"headers":[],"relativePath":"qurasdirma.md","filePath":"qurasdirma.md"}'),o={name:"qurasdirma.md"};function s(e,a,d,m,u,h){return l(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="qurasdırma-və-ilk-acılıs" tabindex="-1">Quraşdırma və ilk açılış <a class="header-anchor" href="#qurasdırma-və-ilk-acılıs" aria-label="Permalink to &quot;Quraşdırma və ilk açılış&quot;">​</a></h1><p>Bu səhifə proqramı quraşdıran adam üçündür (adətən mağazanın sahibi). Bir dəfə edilir.</p><h2 id="_1-proqramı-endirmək" tabindex="-1">1. Proqramı endirmək <a class="header-anchor" href="#_1-proqramı-endirmək" aria-label="Permalink to &quot;1. Proqramı endirmək&quot;">​</a></h2><p>Ən son versiya: <strong><a href="https://github.com/Camalzadeh/kassa-releases/releases/latest" target="_blank" rel="noreferrer">Kassa-Setup — endir</a></strong> (<code>Kassa-Setup-….exe</code> faylı).</p><h2 id="_2-qurasdırmaq" tabindex="-1">2. Quraşdırmaq <a class="header-anchor" href="#_2-qurasdırmaq" aria-label="Permalink to &quot;2. Quraşdırmaq&quot;">​</a></h2><ol><li><code>Kassa-Setup-….exe</code> faylını açın.</li><li>Windows &quot;naməlum proqram&quot; desə: <strong>&quot;Daha çox&quot; → &quot;Yenə də işlət&quot;</strong>.</li><li>Dili seçin (Azərbaycanca, Русский, English).</li><li>Quraşdırma növünü seçin: <ul><li><strong>&quot;Bütün istifadəçilər üçün&quot; (mağaza üçün tövsiyə olunur)</strong> — Windows admin parolu soruşulur. Proqram qorunan rejimdə işləyir: kassir proqramı və məlumatları silə bilmir. Bax <a href="#windows">Windows hesabları</a>.</li><li><strong>&quot;Yalnız mənim üçün&quot;</strong> — admin parolu lazım deyil. Sınamaq və ya ev kompüteri üçün.</li></ul></li><li><strong>İrəli → Quraşdır → Bitir</strong>. İş masasında yaşıl <strong>Kassa</strong> ikonu yaranır.</li></ol><h2 id="_3-ilk-acılıs" tabindex="-1">3. İlk açılış <a class="header-anchor" href="#_3-ilk-acılıs" aria-label="Permalink to &quot;3. İlk açılış&quot;">​</a></h2><p><img src="'+r+'" alt="İlk quraşdırma"></p><ol><li><strong>Quraşdırma parolu</strong> — proqramı sizə verən şəxsdən alın. Yalnız ilk dəfə soruşulur.</li><li>Dili, <strong>mağazanın adını</strong>, <strong>öz adınızı</strong> və <strong>parolunuzu</strong> yazın (ən az 8 simvol, hərf və rəqəm). Siz mağazanın <strong>admini</strong> olursunuz.</li><li><strong>Quraşdır</strong>.</li></ol><h2 id="_4-bərpa-kodu-—-mutləq-kagıza-yazın" tabindex="-1">4. Bərpa kodu — mütləq kağıza yazın <a class="header-anchor" href="#_4-bərpa-kodu-—-mutləq-kagıza-yazın" aria-label="Permalink to &quot;4. Bərpa kodu — mütləq kağıza yazın&quot;">​</a></h2><p>Quraşdırmadan sonra ekranda <strong>bərpa kodu</strong> çıxır.</p><ul><li>Onu <strong>kağıza yazın</strong> və evdə və ya seyfdə saxlayın. Kompüterdə fayl kimi saxlamayın.</li><li>Kompüter xarab olsa və ya oğurlansa, məlumatları <strong>yalnız bu kodla</strong> qaytarmaq olar.</li><li>Sonra da görmək olar: <strong>Backup → Bərpa kodu</strong> → parolunuz.</li></ul><p><strong>&quot;Kodu yazdım&quot;</strong> qutusunu işarələyin → <strong>Davam et</strong>.</p><h2 id="windows" tabindex="-1">5. Windows hesabları: kassir üçün ayrıca hesab <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;5. Windows hesabları: kassir üçün ayrıca hesab {#windows}&quot;">​</a></h2><p>Ən etibarlı qoruma (&quot;Bütün istifadəçilər üçün&quot; quraşdırılanda):</p><ol><li><strong>Sahib</strong> üçün Windows-da <strong>parollu admin</strong> hesabı — Kassa-nı o quraşdırır və yeniləyir.</li><li><strong>Kassir</strong> üçün <strong>standart</strong> (admin olmayan) hesab: Parametrlər → Hesablar → Digər istifadəçilər → <strong>Hesab əlavə et</strong> → hesab növü <strong>&quot;Standart istifadəçi&quot;</strong>.</li><li>Kompüter hər gün <strong>kassirin hesabında</strong> açılır. Kassa orada da işləyir, amma kassir proqramı və məlumat fayllarını silə və ya dəyişə bilmir.</li><li>Kassa-ya hər kəs öz <strong>Kassa adı və parolu</strong> ilə daxil olur (bunlar Windows parolundan ayrıdır).</li></ol><p>Bu rejimdə pəncərəni bağlamaq proqramı tam dayandırmır — arxa planda işləyir (Telegram hesabatı, backup). Bu normaldır.</p><h2 id="_6-sonra-nə-etməli" tabindex="-1">6. Sonra nə etməli <a class="header-anchor" href="#_6-sonra-nə-etməli" aria-label="Permalink to &quot;6. Sonra nə etməli&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Addım</th><th>Harada</th></tr></thead><tbody><tr><td>Mağaza məlumatları (ünvan, telefon, VÖEN — qəbzdə görünür)</td><td><a href="./ayarlar.html">Ayarlar</a></td></tr><tr><td>Kassir hesabı</td><td><a href="./istifadeciler.html">İstifadəçilər</a></td></tr><tr><td>Malları daxil etmək</td><td><a href="./mallar.html">Mallar</a>, <a href="./mal-qebulu.html">Mal qəbulu</a></td></tr><tr><td>Çek və etiket printeri</td><td><a href="./printerler.html">Printer</a></td></tr><tr><td>Telefona gündəlik hesabat və backup</td><td><a href="./telegram.html">Telegram</a></td></tr><tr><td>Həftəlik USB backup</td><td><a href="./backup.html">Backup</a></td></tr></tbody></table>',19)])])}const k=t(o,[["render",s]]);export{p as __pageData,k as default};
